// Offline-first: every file is stored when a version installs, and always served from the device.
// Network is only used for files not stored yet and for the version check, so a flaky or
// captive in-flight Wi-Fi can never break or overwrite the app.
const VERSION = '__VERSION__';
const CACHE = 'safetalk-' + VERSION;
const ASSETS = __ASSETS__;
const WANT = { js: 'javascript', css: 'css', html: 'html', json: 'json', webmanifest: 'json', woff2: 'font', webp: 'image', jpg: 'image', png: 'image', svg: 'svg' };

// only keep real files, never a login/portal page or a redirect
function genuine(url, res) {
  if (!res || !res.ok || res.redirected || res.type === 'opaqueredirect') return false;
  const path = new URL(url, self.location).pathname;
  const ext = path.endsWith('/') ? 'html' : (path.split('.').pop() || '').toLowerCase();
  const want = WANT[ext];
  return !want || (res.headers.get('content-type') || '').toLowerCase().includes(want);
}
function timeout(ms) { return new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), ms)); }

self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    const todo = ASSETS.slice();
    const worker = async () => {
      while (todo.length) {
        const u = todo.shift();
        const res = await fetch(new Request(u, { cache: 'reload' }));
        if (!genuine(u, res)) throw new Error('bad response for ' + u); // abort: keep the old version
        await c.put(u, res);
      }
    };
    await Promise.all([worker(), worker(), worker(), worker()]);
    await self.skipWaiting();
  })().catch(async err => { await caches.delete(CACHE); throw err; }));
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('safetalk-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;

  if (url.pathname.endsWith('/version.json')) { // version check: network only, short timeout
    e.respondWith(Promise.race([fetch(req, { cache: 'no-store' }), timeout(5000)])
      .catch(() => new Response('{}', { status: 503, headers: { 'content-type': 'application/json' } })));
    return;
  }

  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    const hit = await c.match(req, { ignoreSearch: true }) ||
      (req.mode === 'navigate' ? await c.match('index.html') || await c.match('./') : null);
    if (hit) return hit;
    try {
      const res = await Promise.race([fetch(req), timeout(8000)]);
      if (genuine(req.url, res)) c.put(req, res.clone());
      return res;
    } catch (err) {
      const any = await caches.match(req, { ignoreSearch: true }) || (req.mode === 'navigate' ? await caches.match('index.html') : null);
      if (any) return any;
      throw err;
    }
  })());
});

// offline status for the app's settings sheet
self.addEventListener('message', e => {
  if (!e.data || e.data.type !== 'status' || !e.ports[0]) return;
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    const keys = new Set((await c.keys()).map(r => new URL(r.url).pathname));
    const base = new URL('./', self.location).pathname;
    const have = ASSETS.filter(a => keys.has(base + (a === './' ? '' : a))).length;
    e.ports[0].postMessage({ version: VERSION, have, total: ASSETS.length });
  })());
});
